  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${safeTitle}</title>
  <style>${styles}</style>
</head>
<body>
  <header><a href="/index.html">Home</a></header>
  <main>
    <h1>${safeTitle}</h1>${metadata}
    ${body}
  </main>
